// Expo config plugin: signs release builds with my own key instead of the public debug key.
//
// android/ is regenerated by `expo prebuild --clean`, so the signing setup can't be edited there
// directly; this plugin writes it into android/app/build.gradle on every prebuild.
//
// The key and its passwords never enter the project. They're read from ~/.gradle/gradle.properties:
//   KANJIPRO_RELEASE_STORE_FILE=/absolute/path/to/kanjipro-release.jks
//   KANJIPRO_RELEASE_KEY_ALIAS=kanjipro
//   KANJIPRO_RELEASE_STORE_PASSWORD=...
//   KANJIPRO_RELEASE_KEY_PASSWORD=...
// Without them, a release build stops with an error instead of quietly using the debug key:
// Android only installs updates signed with the same key as the installed version.
const { withAppBuildGradle } = require('expo/config-plugins')

const MARKER = '// withReleaseSigning'

const RELEASE_SIGNING_CONFIG = `
        release { ${MARKER}
            if (findProperty('KANJIPRO_RELEASE_STORE_FILE')) {
                storeFile file(findProperty('KANJIPRO_RELEASE_STORE_FILE'))
                storePassword findProperty('KANJIPRO_RELEASE_STORE_PASSWORD')
                keyAlias findProperty('KANJIPRO_RELEASE_KEY_ALIAS')
                keyPassword findProperty('KANJIPRO_RELEASE_KEY_PASSWORD')
            }
        }`

const MISSING_KEY_CHECK = `
${MARKER}: refuse to build a release without the release key (see plugins/withReleaseSigning.js).
gradle.taskGraph.whenReady { graph ->
    def buildsRelease = graph.allTasks.any { it.name ==~ /(assemble|bundle|package)Release/ }
    if (buildsRelease && !findProperty('KANJIPRO_RELEASE_STORE_FILE')) {
        throw new GradleException(
            'Release signing key not configured. Add the KANJIPRO_RELEASE_* entries to ' +
            '~/.gradle/gradle.properties (see plugins/withReleaseSigning.js).')
    }
}
`

// Replaces exactly one occurrence, so a changed Expo template fails loudly instead of silently
// producing a debug-signed release.
const replaceOnce = (text, search, replacement, what) => {
    const count = text.split(search).length - 1
    if (count !== 1) {
        throw new Error(`withReleaseSigning: expected 1 ${what} in app/build.gradle, found ${count}`)
    }
    return text.replace(search, replacement)
}

const withReleaseSigning = (config) => withAppBuildGradle(config, (config) => {
    let gradle = config.modResults.contents
    if (gradle.includes(MARKER)) return config // already applied

    gradle = replaceOnce(gradle, 'signingConfigs {', `signingConfigs {${RELEASE_SIGNING_CONFIG}`, 'signingConfigs block')

    // The release build type is the only one using the debug key after a "Caution!" comment.
    const releaseType = /(release \{\s*\n\s*\/\/ Caution![^\n]*\n[^\n]*\n\s*)signingConfig signingConfigs\.debug/
    if (!releaseType.test(gradle)) {
        throw new Error('withReleaseSigning: release build type not found in app/build.gradle')
    }
    gradle = gradle.replace(releaseType, '$1signingConfig signingConfigs.release')

    config.modResults.contents = gradle + MISSING_KEY_CHECK
    return config
})

module.exports = withReleaseSigning
